        AND a.gugun_code = #{gugunCode}


        AND a.status = #{status}




        AND a.accommodation_type = #{accommodationType}




        AND (a.title LIKE CONCAT('%', #{keyword}, '%')
        OR a.description LIKE CONCAT('%', #{keyword}, '%')
        OR a.address LIKE CONCAT('%', #{keyword}, '%'))




        AND EXISTS (
        SELECT 1 FROM rooms r
        WHERE r.accommodation_id = a.accommodation_id

            AND r.price_per_night BETWEEN #{minPrice} AND #{maxPrice}


            AND r.price_per_night >= #{minPrice}


